const CP1252_BYTE_BY_CHAR = new Map(Object.entries({
  128: "\u20ac",
  130: "\u201a",
  131: "\u0192",
  132: "\u201e",
  133: "\u2026",
  134: "\u2020",
  135: "\u2021",
  136: "\u02c6",
  137: "\u2030",
  138: "\u0160",
  139: "\u2039",
  140: "\u0152",
  142: "\u017d",
  145: "\u2018",
  146: "\u2019",
  147: "\u201c",
  148: "\u201d",
  149: "\u2022",
  150: "\u2013",
  151: "\u2014",
  152: "\u02dc",
  153: "\u2122",
  154: "\u0161",
  155: "\u203a",
  156: "\u0153",
  158: "\u017e",
  159: "\u0178",
}).map(([byte, char]) => [char, Number(byte)]));
const MOJIBAKE_MARKERS = /[\u00c3\u00c2\u00e2\u00d0\u00d1\u00e3\u00e4\u00e5\u00e6\u00e7\u00e8\u00e9\u00ef][\u0080-\uFFFF]/u;
const UTF8_DECODER = typeof TextDecoder === "function" ? new TextDecoder("utf-8", { fatal: true }) : null;

function repairMojibakeText(value) {
  if (!UTF8_DECODER || typeof value !== "string" || !MOJIBAKE_MARKERS.test(value)) return value;
  const bytes = [];
  for (const char of value) {
    const code = char.codePointAt(0);
    if (code <= 255) {
      bytes.push(code);
      continue;
    }
    const byte = CP1252_BYTE_BY_CHAR.get(char);
    if (byte === undefined) return value;
    bytes.push(byte);
  }
  try {
    return UTF8_DECODER.decode(new Uint8Array(bytes));
  } catch {
    return value;
  }
}

function repairLanguageText() {
  LANGUAGE_OPTIONS.forEach((item) => {
    item.short = repairMojibakeText(item.short);
    item.label = repairMojibakeText(item.label);
  });

  Object.values(LANGUAGE_PHRASES).forEach((translations) => {
    if (!Array.isArray(translations)) return;
    translations.forEach((value, index) => {
      translations[index] = repairMojibakeText(value);
    });
  });
}

