Object.assign(LANGUAGE_PHRASES,{"Use an older wallet version if you need these coins.": ["Nutzen Sie eine \u00e4ltere Wallet-Version, wenn Sie diese Coins ben\u00f6tigen.", "Utilisez une ancienne version du portefeuille si vous avez besoin de ces monnaies.", "\u5982\u9700\u4f7f\u7528\u8fd9\u4e9b\u5e01\u79cd\uff0c\u8bf7\u4f7f\u7528\u65e7\u7248\u672c\u94b1\u5305\u3002", "\u3053\u308c\u3089\u306e\u901a\u8ca8\u304c\u5fc5\u8981\u306a\u5834\u5408\u306f\u65e7\u30d0\u30fc\u30b8\u30e7\u30f3\u306e\u30a6\u30a9\u30ec\u30c3\u30c8\u3092\u3054\u5229\u7528\u304f\u3060\u3055\u3044\u3002", "\u0415\u0441\u043b\u0438 \u043d\u0443\u0436\u043d\u044b \u044d\u0442\u0438 \u043c\u043e\u043d\u0435\u0442\u044b, \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0439\u0442\u0435 \u0441\u0442\u0430\u0440\u0443\u044e \u0432\u0435\u0440\u0441\u0438\u044e \u043a\u043e\u0448\u0435\u043b\u044c\u043a\u0430.", "\u042f\u043a\u0449\u043e \u043f\u043e\u0442\u0440\u0456\u0431\u043d\u0456 \u0446\u0456 \u043c\u043e\u043d\u0435\u0442\u0438, \u0441\u043a\u043e\u0440\u0438\u0441\u0442\u0430\u0439\u0442\u0435\u0441\u044f \u0441\u0442\u0430\u0440\u043e\u044e \u0432\u0435\u0440\u0441\u0456\u0454\u044e \u0433\u0430\u043c\u0430\u043d\u0446\u044f."], "Release changes": ["\u00c4nderungen der Version", "Modifications de la version", "\u7248\u672c\u53d8\u66f4", "\u30ea\u30ea\u30fc\u30b9\u306e\u5909\u66f4\u70b9", "\u0418\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u0432\u0435\u0440\u0441\u0438\u0438", "\u0417\u043c\u0456\u043d\u0438 \u0432\u0435\u0440\u0441\u0456\u0457"]});
