const translatedTextNodes = new WeakMap();
let languageApplying = false;
let languageQueued = false;

function translatePhrase(value, language = activeLanguage) {
  if (language === "en") return value;
  const index = LANGUAGE_CODES.indexOf(language);
  if (index < 0) return value;
  const translations = LANGUAGE_PHRASES[value];
  return translations?.[index] || value;
}

function withOriginalSpacing(original, translated) {
  const leading = original.match(/^\s*/)?.[0] || "";
  const trailing = original.match(/\s*$/)?.[0] || "";
  return `${leading}${translated}${trailing}`;
}

function isKnownRenderedTranslation(current, original) {
  const key = original.trim();
  return current === key || Boolean(LANGUAGE_PHRASES[key]?.includes(current));
}

function shouldSkipTranslation(node) {
  const element = node.nodeType === Node.ELEMENT_NODE ? node : node.parentElement;
  return !element || Boolean(element.closest("script, style, noscript, svg, code, pre, textarea, [data-i18n-static]"));
}

function translateTextNode(node) {
  if (shouldSkipTranslation(node)) return;
  let original = translatedTextNodes.get(node);
  if (original) {
    const current = node.nodeValue.trim();
    if (current && !isKnownRenderedTranslation(current, original)) {
      translatedTextNodes.delete(node);
      original = null;
    }
  }
  original ||= node.nodeValue;
  const key = original.trim();
  if (!key) return;
  if (!Object.prototype.hasOwnProperty.call(LANGUAGE_PHRASES, key)) return;
  if (!translatedTextNodes.has(node)) translatedTextNodes.set(node, original);
  const translated = withOriginalSpacing(original, translatePhrase(key));
  if (node.nodeValue !== translated) node.nodeValue = translated;
}

function translateElementAttributes(element) {
  if (shouldSkipTranslation(element)) return;
  ["placeholder", "aria-label", "title", "alt"].forEach((attribute) => {
    if (!element.hasAttribute(attribute)) return;
    const cacheName = `data-i18n-${attribute}`;
    let original = element.getAttribute(cacheName);
    if (original) {
      const current = element.getAttribute(attribute);
      if (current && !isKnownRenderedTranslation(current, original)) {
        element.removeAttribute(cacheName);
        original = null;
      }
    }
    original ||= element.getAttribute(attribute);
    if (!Object.prototype.hasOwnProperty.call(LANGUAGE_PHRASES, original)) return;
    if (!element.hasAttribute(cacheName)) element.setAttribute(cacheName, original);
    const translated = translatePhrase(original);
    if (element.getAttribute(attribute) !== translated) element.setAttribute(attribute, translated);
  });
}

function applyLanguage(root = document.body) {
  if (!root) return;
  languageApplying = true;
  document.documentElement.lang = activeLanguage;
  if (root.nodeType === Node.TEXT_NODE) {
    translateTextNode(root);
  } else {
    if (root.nodeType === Node.ELEMENT_NODE) translateElementAttributes(root);
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode: (node) => shouldSkipTranslation(node) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT,
    });
    while (walker.nextNode()) translateTextNode(walker.currentNode);
    root.querySelectorAll?.("[placeholder], [aria-label], [title], img[alt]").forEach(translateElementAttributes);
  }
  document.title = translatePhrase(originalDocumentTitle);
  if (metaDescription && originalMetaDescription) {
    metaDescription.setAttribute("content", translatePhrase(originalMetaDescription));
  }
  renderLanguageSelectorState();
  languageApplying = false;
}

function queueLanguageApply(root = document.body) {
  if (languageApplying || languageQueued) return;
  languageQueued = true;
  requestAnimationFrame(() => {
    languageQueued = false;
    applyLanguage(root);
  });
}

function renderLanguageSelectorState() {
  const current = LANGUAGE_OPTIONS.find((item) => item.code === activeLanguage) || LANGUAGE_OPTIONS[0];
  document.querySelectorAll("[data-language-current]").forEach((node) => {
    node.textContent = current.short;
  });
  document.querySelectorAll("[data-language-title]").forEach((node) => {
    node.textContent = translatePhrase("Language");
  });
  document.querySelectorAll("[data-language-subtitle]").forEach((node) => {
    node.textContent = translatePhrase("Choose interface language");
  });
  document.querySelectorAll("[data-language-option]").forEach((button) => {
    const isActive = button.dataset.languageOption === activeLanguage;
    button.classList.toggle("active", isActive);
    button.setAttribute("aria-pressed", String(isActive));
  });
  document.querySelectorAll(".language-toggle").forEach((button) => {
    button.setAttribute("aria-label", translatePhrase("Switch language"));
  });
}

function initLanguageSelector() {
  const navActions = document.querySelector(".nav-actions");
  if (!navActions || navActions.querySelector(".language-selector")) return;
  const selector = document.createElement("div");
  selector.className = "language-selector";
  selector.innerHTML = `
    <button class="language-toggle" type="button" aria-haspopup="true" aria-expanded="false" aria-label="Switch language">
      <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Zm6.9 9h-3.1a15.3 15.3 0 0 0-1.2-5 8.1 8.1 0 0 1 4.3 5ZM12 4.1c.8 1.2 1.5 3.7 1.7 6.9h-3.4c.2-3.2.9-5.7 1.7-6.9ZM4.3 13h3.9c.1 1.8.4 3.5.9 4.8A8.1 8.1 0 0 1 4.3 13Zm3.9-2H5.1a8.1 8.1 0 0 1 4.3-5 15.3 15.3 0 0 0-1.2 5Zm3.8 8.9c-.8-1.2-1.5-3.7-1.7-6.9h3.4c-.2 3.2-.9 5.7-1.7 6.9Zm2.9-2.1c.5-1.3.8-3 .9-4.8h3.9a8.1 8.1 0 0 1-4.8 4.8Z"/></svg>
      <span data-language-current data-i18n-static></span>
    </button>
    <div class="language-menu" data-i18n-static>
      <div class="language-menu-head">
        <strong data-language-title></strong>
        <span data-language-subtitle></span>
      </div>
      <div class="language-options">
        ${LANGUAGE_OPTIONS.map((item) => `<button type="button" data-language-option="${item.code}" aria-pressed="false"><span>${item.label}</span><b>${item.short}</b></button>`).join("")}
      </div>
    </div>
  `;
  const themeToggle = navActions.querySelector(".theme-toggle");
  navActions.insertBefore(selector, themeToggle || navActions.firstElementChild);

  const toggle = selector.querySelector(".language-toggle");
  toggle.addEventListener("click", () => {
    const isOpen = selector.classList.toggle("open");
    toggle.setAttribute("aria-expanded", String(isOpen));
  });
  selector.querySelectorAll("[data-language-option]").forEach((button) => {
    button.addEventListener("click", () => {
      activeLanguage = button.dataset.languageOption;
      localStorage.setItem(LANGUAGE_STORAGE_KEY, activeLanguage);
      selector.classList.remove("open");
      toggle.setAttribute("aria-expanded", "false");
      applyLanguage(document.body);
      document.dispatchEvent(new CustomEvent("altbase:languagechange", { detail: { language: activeLanguage } }));
    });
  });
  document.addEventListener("click", (event) => {
    if (selector.contains(event.target)) return;
    selector.classList.remove("open");
    toggle.setAttribute("aria-expanded", "false");
  });
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    selector.classList.remove("open");
    toggle.setAttribute("aria-expanded", "false");
  });
}

function normalizePath(value) {
  const url = new URL(value, window.location.origin);
  const pathname = url.pathname.replace(/\/index(?:\.html)?$/, "/").replace(/\.html$/, "");
  return pathname === "" ? "/" : pathname;
}

const currentPage = normalizePath(window.location.pathname);
const savedTheme = localStorage.getItem("altbase-theme") || "light";

document.documentElement.dataset.theme = savedTheme;

document.querySelectorAll(".nav-links a").forEach((link) => {
  const href = normalizePath(link.getAttribute("href"));
  if (href === currentPage || (href !== "/" && currentPage.startsWith(`${href}/`))) {
    link.classList.add("active");
  }
});

const menuToggle = document.querySelector(".menu-toggle");
const navLinks = document.querySelector(".nav-links");

if (menuToggle && navLinks) {
  menuToggle.addEventListener("click", () => {
    navLinks.classList.toggle("open");
    menuToggle.setAttribute("aria-expanded", String(navLinks.classList.contains("open")));
  });
}

const navActions = document.querySelector(".nav-actions");
const isAdminPage = document.title.toLowerCase().includes("admin");

if (navActions && !isAdminPage && !navActions.querySelector(".nav-social")) {
  const navSocial = document.createElement("div");
  navSocial.className = "nav-social";
  navSocial.setAttribute("aria-label", "Altbase Wallet social links");
  navSocial.innerHTML = `
    <a class="social-icon" href="https://discord.gg/4BTRfSYqPN" target="_blank" rel="noopener noreferrer" aria-label="Altbase Wallet Discord">
      <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19.7 5.7A15.8 15.8 0 0 0 15.8 4l-.2.3c1.4.4 2.1 1 2.1 1a13.6 13.6 0 0 0-12.4 0s.7-.6 2.2-1L7.2 4a15.8 15.8 0 0 0-3.9 1.7C.8 9.4.1 13 .5 16.6A15.9 15.9 0 0 0 5.4 19s.6-.8 1.1-1.5c-2.1-.6-2.9-1.9-2.9-1.9l.5.3c2.3 1.3 4.5 1.7 6.5 1.6 1.6 0 3.5-.3 5.5-1.4.4-.2.8-.5.8-.5s-.8 1.3-3 1.9c.5.7 1.1 1.5 1.1 1.5a15.8 15.8 0 0 0 4.9-2.4c.5-4.2-.7-7.7-2.8-10.9ZM8.3 14.5c-.9 0-1.6-.8-1.6-1.8s.7-1.8 1.6-1.8 1.6.8 1.6 1.8-.7 1.8-1.6 1.8Zm5.8 0c-.9 0-1.6-.8-1.6-1.8s.7-1.8 1.6-1.8 1.6.8 1.6 1.8-.7 1.8-1.6 1.8Z"/></svg>
    </a>
    <a class="social-icon" href="https://x.com/altbasewallet" target="_blank" rel="noopener noreferrer" aria-label="Altbase Wallet on X">
      <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M14.1 10.6 22.2 1h-1.9l-7.1 8.3L7.6 1H1.1l8.5 12.4L1.1 23h1.9l7.4-8.6 5.9 8.6h6.5l-8.8-12.4Zm-2.6 3-0.9-1.2L3.8 2.5h2.9l5.5 7.9.9 1.2 7.2 10.2h-2.9l-5.9-8.3Z"/></svg>
    </a>
  `;

  navActions.insertBefore(navSocial, navActions.firstElementChild);
}

initLanguageSelector();

document.querySelectorAll(".faq-item button").forEach((button) => {
  button.addEventListener("click", () => {
    button.closest(".faq-item").classList.toggle("open");
  });
});

document.querySelectorAll(".theme-toggle").forEach((button) => {
  button.addEventListener("click", () => {
    const nextTheme = document.documentElement.dataset.theme === "dark" ? "light" : "dark";
    document.documentElement.dataset.theme = nextTheme;
    localStorage.setItem("altbase-theme", nextTheme);
    document.querySelectorAll(".theme-toggle").forEach((toggle) => {
      toggle.setAttribute("aria-label", nextTheme === "dark" ? "Switch to light theme" : "Switch to dark theme");
      toggle.textContent = nextTheme === "dark" ? "Light" : "Dark";
    });
  });

  button.setAttribute("aria-label", savedTheme === "dark" ? "Switch to light theme" : "Switch to dark theme");
  button.textContent = savedTheme === "dark" ? "Light" : "Dark";
});

const cookieBanner = document.querySelector(".cookie-banner");

if (cookieBanner) {
  const cookieChoice = localStorage.getItem("altbase-cookie-consent");
  if (!cookieChoice) {
    cookieBanner.classList.add("show");
  }

  cookieBanner.querySelectorAll("[data-cookie-choice]").forEach((button) => {
    button.addEventListener("click", () => {
      localStorage.setItem("altbase-cookie-consent", button.dataset.cookieChoice);
      cookieBanner.classList.remove("show");
    });
  });
}

applyLanguage(document.body);

const languageObserver = new MutationObserver((mutations) => {
  if (languageApplying) return;
  if (!mutations.some((mutation) => mutation.type === "childList" || mutation.type === "characterData" || mutation.type === "attributes")) return;
  queueLanguageApply(document.body);
});

languageObserver.observe(document.body, {
  childList: true,
  subtree: true,
  characterData: true,
  attributes: true,
  attributeFilter: ["placeholder", "aria-label", "title", "alt"],
});

window.AltbaseI18n = {
  apply: applyLanguage,
  t: translatePhrase,
  get language() {
    return activeLanguage;
  },
  setLanguage(language) {
    if (!LANGUAGE_OPTIONS.some((item) => item.code === language)) return;
    activeLanguage = language;
    localStorage.setItem(LANGUAGE_STORAGE_KEY, activeLanguage);
    applyLanguage(document.body);
  },
};

